-- 27 Nov 2026 final admin improvements. Safe to run twice.
-- 1) Legal documents: the Terms & Conditions and the Privacy Policy are edited in Settings as drafts and published to the
--    website. Until now the website showed the terms built into the code (V4) and never what the editor saved, so the
--    rows saved so far become drafts (deletable), V4 and the current privacy text are seeded as the live versions, and
--    bookings stamped with an editor version are re-stamped 4: the V4 text is what the website showed them.
ALTER TABLE "terms_versions" ADD COLUMN IF NOT EXISTS "doc" text DEFAULT 'terms' NOT NULL;--> statement-breakpoint
ALTER TABLE "terms_versions" ADD COLUMN IF NOT EXISTS "status" text DEFAULT 'published' NOT NULL;--> statement-breakpoint
-- Rows saved from now on are drafts unless published (the old editor, still running during the deploy, saves without a status)
ALTER TABLE "terms_versions" ALTER COLUMN "status" SET DEFAULT 'draft';--> statement-breakpoint
ALTER TABLE "terms_versions" ADD COLUMN IF NOT EXISTS "effective_on" date;--> statement-breakpoint
ALTER TABLE "terms_versions" ADD COLUMN IF NOT EXISTS "published_by" uuid REFERENCES "admin_users"("id") ON DELETE set null;--> statement-breakpoint
ALTER TABLE "terms_versions" ADD COLUMN IF NOT EXISTS "published_at" timestamp with time zone;--> statement-breakpoint
DO $$ BEGIN
  ALTER TABLE "terms_versions" ADD CONSTRAINT "terms_versions_doc_check" CHECK ("doc" in ('terms', 'privacy'));
EXCEPTION WHEN duplicate_object THEN NULL; END $$;--> statement-breakpoint
DO $$ BEGIN
  ALTER TABLE "terms_versions" ADD CONSTRAINT "terms_versions_status_check" CHECK ("status" in ('draft', 'published'));
EXCEPTION WHEN duplicate_object THEN NULL; END $$;--> statement-breakpoint
UPDATE "terms_versions" SET "status" = 'draft'
  WHERE "published_at" IS NULL AND NOT EXISTS (SELECT 1 FROM "terms_versions" WHERE "published_at" IS NOT NULL);--> statement-breakpoint
UPDATE "terms_versions" SET "version" = left("version", 30) || ' (draft)'
  WHERE "doc" = 'terms' AND "version" = '4' AND "status" = 'draft'
  AND NOT EXISTS (SELECT 1 FROM "terms_versions" WHERE "doc" = 'terms' AND "status" = 'published');--> statement-breakpoint
DROP INDEX IF EXISTS "terms_versions_version_key";--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "terms_versions_doc_version_key" ON "terms_versions" ("doc", "version");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "terms_versions_live_idx" ON "terms_versions" ("doc", "status", "published_at");--> statement-breakpoint
