  WHERE q."vehicle" = v."id" AND v."model_key" IS NOT NULL AND v."model_key" <> v."id";--> statement-breakpoint
UPDATE "quote_requests" q SET "vehicles" = (
    SELECT jsonb_agg(CASE WHEN m."model_key" IS NOT NULL THEN jsonb_set(x.e, '{key}', to_jsonb(m."model_key")) ELSE x.e END ORDER BY x.ord)
    FROM jsonb_array_elements(q."vehicles") WITH ORDINALITY AS x(e, ord)
    LEFT JOIN "vehicles" m ON m."id" = x.e->>'key' AND m."model_key" IS NOT NULL AND m."model_key" <> m."id"
  )
  WHERE jsonb_typeof(q."vehicles") = 'array'
  AND EXISTS (
    SELECT 1 FROM jsonb_array_elements(q."vehicles") AS y(e)
    JOIN "vehicles" n ON n."id" = y.e->>'key' AND n."model_key" IS NOT NULL AND n."model_key" <> n."id"
  );
--> statement-breakpoint
-- 4) Close protection added after booking (lib/admin/charges.ts): with the balance more than 30 days out, else invoiced on its own.
CREATE TABLE IF NOT EXISTS "booking_charges" (
  "id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
  "request_id" uuid NOT NULL REFERENCES "quote_requests"("id") ON DELETE cascade,
  "kind" text DEFAULT 'close_protection' NOT NULL,
  "description" text NOT NULL,
  "amount_cents" integer NOT NULL,
  "vat_basis_points" integer DEFAULT 2100 NOT NULL,
  "billing" text NOT NULL,
  "status" text DEFAULT 'active' NOT NULL,
  "accepted_at" timestamp with time zone,
  "moneybird_id" text,
  "invoice_number" text,
  "invoice_state" text,
  "invoice_url" text,
  "invoiced_at" timestamp with time zone,
  "paid_at" timestamp with time zone,
  "last_error" text,
  "claimed_at" timestamp with time zone,
  "created_by" uuid REFERENCES "admin_users"("id") ON DELETE set null,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "cancelled_by" uuid REFERENCES "admin_users"("id") ON DELETE set null,
  "cancelled_at" timestamp with time zone,
  CONSTRAINT "booking_charges_amount_check" CHECK ("amount_cents" > 0),
  CONSTRAINT "booking_charges_billing_check" CHECK ("billing" in ('balance', 'separate')),
  CONSTRAINT "booking_charges_status_check" CHECK ("status" in ('active', 'cancelled'))
);--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "booking_charges_request_idx" ON "booking_charges" ("request_id");
--> statement-breakpoint
-- 5) The newsletter list (lib/marketing/contacts.ts), filled with everyone who ticked "news and offers" so far: on a booking
--    (newest consent per address) or on a verified corporate sign-up. Mailchimp gets them once it is connected.
CREATE TABLE IF NOT EXISTS "marketing_contacts" (
  "id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
  "email" text NOT NULL,
  "name" text,
  "source" text NOT NULL,
  "source_ref" text,
  "status" text DEFAULT 'subscribed' NOT NULL,
  "consented_at" timestamp with time zone,
  "unsubscribed_at" timestamp with time zone,
  "sync_pending" boolean DEFAULT true NOT NULL,
  "synced_at" timestamp with time zone,
  "sync_error" text,
  "notes" text,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT "marketing_contacts_status_check" CHECK ("status" in ('subscribed', 'unsubscribed', 'suppressed'))
);--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "marketing_contacts_email_key" ON "marketing_contacts" ("email");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "marketing_contacts_status_idx" ON "marketing_contacts" ("status");--> statement-breakpoint
INSERT INTO "marketing_contacts" ("email", "name", "source", "source_ref", "consented_at")
  SELECT DISTINCT ON (lower(trim("email"))) lower(trim("email")), "name", 'booking', "reference", "created_at"
  FROM "quote_requests"
  WHERE "marketing_consent" = true AND lower(trim("email")) ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
  ORDER BY lower(trim("email")), "created_at" DESC
ON CONFLICT ("email") DO NOTHING;--> statement-breakpoint
INSERT INTO "marketing_contacts" ("email", "name", "source", "source_ref", "consented_at")
  SELECT lower(trim("email")), "name", 'corporate', "company_name", coalesce("consented_at", "created_at")
  FROM "corporate_contacts"
  WHERE "marketing_consent" = true AND lower(trim("email")) ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
ON CONFLICT ("email") DO NOTHING;
